package studio.solocamera;
import android.content.Context;import android.graphics.*;import android.view.*;
/** Draggable five-point tone curve; endpoints are movable vertically. */
final class EditorToneCurveView extends View {
 interface Listener{void begin();void changed();void end();}
 private final Paint p=new Paint(3);private final EditorProject.Clip clip;private final int channel;private final Listener listener;private double[] points;private int active=-1;private final float d;
 EditorToneCurveView(Context c,EditorProject.Clip clip,int channel,Listener listener){super(c);this.clip=clip;this.channel=channel;this.listener=listener;d=getResources().getDisplayMetrics().density;points=channel==0?clip.curveMaster:channel==1?clip.curveRed:channel==2?clip.curveGreen:clip.curveBlue;setContentDescription("Tone curve editor");setMinimumHeight((int)(180*d));}
 protected void onDraw(Canvas canvas){float pad=18*d,w=getWidth()-2*pad,h=getHeight()-2*pad;canvas.drawColor(0xff11161d);p.setColor(0xff303a46);p.setStrokeWidth(d);for(int i=0;i<=4;i++){float x=pad+w*i/4,y=pad+h*i/4;canvas.drawLine(x,pad,x,pad+h,p);canvas.drawLine(pad,y,pad+w,y,p);}p.setColor(channel==1?0xffff6b69:channel==2?0xff62d891:channel==3?0xff65a9ff:0xffffc857);p.setStrokeWidth(2.5f*d);p.setStyle(Paint.Style.STROKE);Path path=new Path();for(int i=0;i<points.length;i++){float x=pad+w*i/4,y=pad+h*(1-(float)points[i]);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}canvas.drawPath(path,p);p.setStyle(Paint.Style.FILL);for(int i=0;i<points.length;i++){float x=pad+w*i/4,y=pad+h*(1-(float)points[i]);p.setColor(i==active?Color.WHITE:0xffedf0f3);canvas.drawCircle(x,y,(i==active?7:5)*d,p);}}
 public boolean onTouchEvent(MotionEvent e){float pad=18*d,w=getWidth()-2*pad,h=getHeight()-2*pad;if(e.getAction()==MotionEvent.ACTION_DOWN){float x=(e.getX()-pad)/w;active=Math.max(0,Math.min(4,Math.round(x*4)));listener.begin();update(e.getY(),pad,h);return true;}if(e.getAction()==MotionEvent.ACTION_MOVE&&active>=0){update(e.getY(),pad,h);listener.changed();invalidate();return true;}if((e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL)&&active>=0){update(e.getY(),pad,h);active=-1;listener.end();invalidate();return true;}return true;}
 private void update(float y,float pad,float h){points[active]=Math.max(0,Math.min(1,1-(y-pad)/h));if(channel==0)clip.curveMaster=points;else if(channel==1)clip.curveRed=points;else if(channel==2)clip.curveGreen=points;else clip.curveBlue=points;invalidate();}
}
